#include "vll/tutor/StructuredTutor.h"
#include <sstream>
namespace vll::tutor {namespace{std::string esc(const std::string&s){std::string o;for(char c:s){if(c=='"'||c=='\\')o+='\\';if(c=='\n'){o+="\\n";continue;}o+=c;}return o;}}bool StructuredTutor::validate(const TutorPayload&p)const{return !p.conceptId.empty()&&!p.exerciseId.empty()&&!p.facts.empty();}std::string StructuredTutor::offlineExplanation(const TutorPayload&p)const{if(!validate(p))return "No deterministic analysis is available.";std::ostringstream o;o<<p.conceptId<<": ";for(std::size_t i=0;i<p.facts.size();++i){if(i)o<<' ';o<<p.facts[i].fact;}return o.str();}std::string StructuredTutor::jsonPayload(const TutorPayload&p)const{if(!validate(p))return "{}";std::ostringstream o;o<<"{\"conceptId\":\""<<esc(p.conceptId)<<"\",\"exerciseId\":\""<<esc(p.exerciseId)<<"\",\"facts\":[";for(std::size_t i=0;i<p.facts.size();++i){if(i)o<<',';o<<"{\"code\":\""<<esc(p.facts[i].code)<<"\",\"fact\":\""<<esc(p.facts[i].fact)<<"\"}";}return o.str()+"]}";}}
